/* Community Library (round 39), run after part 81 (communities) and part 270. A community's admin turns on a Library (`community_library_settings`, one row per community, off until turned on) and fills it with items (`community_library_items`): one of the creator's own Storelib products attached (product_id, kind product), or files and links uploaded straight into it (kind resource, the files in the community's own folder of Storelib storage, the record their ids). Each item has a title, a description from the product editor's rich text, a cover, a section (`community_library_sections`), its place in the order, draft or published, and who opens it: free for members, members of some tiers, from a points level, bought (a price), or picked members. An uploaded item that is sold becomes a product made for the community (made_product, products.community_id), so a purchase is an ordinary Storelib order with its receipt, payout, refund and place in the buyer's library. `community_library_purchases` keeps which order bought which item (one row per payment, unique), and a full refund marks it. `community_library_activity` counts views (a member once a day) and downloads, through `community_library_touch`, which also keeps the item's two counters. RLS on every new table and nothing granted to members or visitors: only the server reads and writes them, after its own access checks. No existing row changes. Until it runs the Library stays off and says it needs this part. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_library_settings (community_id uuid PRIMARY KEY REFERENCES public.communities(id) ON DELETE CASCADE, enabled boolean NOT NULL DEFAULT false, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.community_library_sections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_library_sections_name_len CHECK (char_length(name) BETWEEN 1 AND 40));
CREATE INDEX IF NOT EXISTS community_library_sections_community_idx ON public.community_library_sections (community_id, position);
CREATE TABLE IF NOT EXISTS public.community_library_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, section_id uuid REFERENCES public.community_library_sections(id) ON DELETE SET NULL, kind text NOT NULL DEFAULT 'resource', product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, made_product boolean NOT NULL DEFAULT false, title text NOT NULL, summary text, description text, cover_url text, files jsonb NOT NULL DEFAULT '[]'::jsonb, links jsonb NOT NULL DEFAULT '[]'::jsonb, access_mode text NOT NULL DEFAULT 'free', tier_ids uuid[] NOT NULL DEFAULT '{}'::uuid[], min_level integer, price_cents integer, currency text, member_ids uuid[] NOT NULL DEFAULT '{}'::uuid[], status text NOT NULL DEFAULT 'draft', position integer NOT NULL DEFAULT 0, view_count integer NOT NULL DEFAULT 0, download_count integer NOT NULL DEFAULT 0, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, CONSTRAINT community_library_items_kind CHECK (kind IN ('resource', 'product')), CONSTRAINT community_library_items_mode CHECK (access_mode IN ('free', 'tier', 'level', 'paid', 'private')), CONSTRAINT community_library_items_status CHECK (status IN ('draft', 'published')), CONSTRAINT community_library_items_title_len CHECK (char_length(title) BETWEEN 1 AND 120), CONSTRAINT community_library_items_summary_len CHECK (summary IS NULL OR char_length(summary) <= 2000), CONSTRAINT community_library_items_description_len CHECK (description IS NULL OR char_length(description) <= 60000), CONSTRAINT community_library_items_cover_len CHECK (cover_url IS NULL OR char_length(cover_url) <= 2000), CONSTRAINT community_library_items_files CHECK (jsonb_typeof(files) = 'array' AND jsonb_array_length(files) <= 20), CONSTRAINT community_library_items_links CHECK (jsonb_typeof(links) = 'array' AND jsonb_array_length(links) <= 10), CONSTRAINT community_library_items_tiers CHECK (cardinality(tier_ids) <= 50), CONSTRAINT community_library_items_members CHECK (cardinality(member_ids) <= 1000), CONSTRAINT community_library_items_level CHECK (min_level IS NULL OR min_level BETWEEN 2 AND 100), CONSTRAINT community_library_items_price CHECK (price_cents IS NULL OR price_cents BETWEEN 50 AND 99999999), CONSTRAINT community_library_items_currency CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$'), CONSTRAINT community_library_items_counts CHECK (view_count >= 0 AND download_count >= 0));
CREATE INDEX IF NOT EXISTS community_library_items_community_idx ON public.community_library_items (community_id, position);
CREATE INDEX IF NOT EXISTS community_library_items_product_idx ON public.community_library_items (product_id) WHERE product_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS public.community_library_purchases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, item_id uuid REFERENCES public.community_library_items(id) ON DELETE SET NULL, user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, product_id uuid REFERENCES public.products(id) ON DELETE SET NULL, order_id uuid REFERENCES public.orders(id) ON DELETE SET NULL, payment_intent_id text NOT NULL, checkout_session_id text, amount_cents integer NOT NULL DEFAULT 0, currency text, created_at timestamptz NOT NULL DEFAULT now(), refunded_at timestamptz, CONSTRAINT community_library_purchases_intent_once UNIQUE (payment_intent_id), CONSTRAINT community_library_purchases_amount CHECK (amount_cents >= 0), CONSTRAINT community_library_purchases_intent_len CHECK (char_length(payment_intent_id) BETWEEN 3 AND 255));
CREATE INDEX IF NOT EXISTS community_library_purchases_item_idx ON public.community_library_purchases (item_id, created_at DESC);
CREATE INDEX IF NOT EXISTS community_library_purchases_community_idx ON public.community_library_purchases (community_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.community_library_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES public.community_library_items(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, kind text NOT NULL, day date NOT NULL DEFAULT current_date, hits integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_library_activity_kind CHECK (kind IN ('view', 'download')), CONSTRAINT community_library_activity_hits CHECK (hits >= 1), CONSTRAINT community_library_activity_once UNIQUE (item_id, user_id, kind, day));
CREATE INDEX IF NOT EXISTS community_library_activity_community_idx ON public.community_library_activity (community_id, day DESC);
CREATE OR REPLACE FUNCTION public.community_library_touch(p_item uuid, p_user uuid, p_kind text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $fn$ DECLARE v_community uuid; v_first boolean; BEGIN IF p_item IS NULL OR p_user IS NULL OR p_kind IS NULL OR p_kind NOT IN ('view', 'download') THEN RETURN; END IF; SELECT community_id INTO v_community FROM public.community_library_items WHERE id = p_item; IF v_community IS NULL THEN RETURN; END IF; INSERT INTO public.community_library_activity AS a (item_id, community_id, user_id, kind, day) VALUES (p_item, v_community, p_user, p_kind, current_date) ON CONFLICT (item_id, user_id, kind, day) DO UPDATE SET hits = a.hits + 1 RETURNING (xmax = 0) INTO v_first; IF p_kind = 'view' AND v_first THEN UPDATE public.community_library_items SET view_count = view_count + 1 WHERE id = p_item; ELSIF p_kind = 'download' THEN UPDATE public.community_library_items SET download_count = download_count + 1 WHERE id = p_item; END IF; END $fn$;
ALTER TABLE public.community_library_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_library_sections ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_library_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_library_purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_library_activity ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_library_settings, public.community_library_sections, public.community_library_items, public.community_library_purchases, public.community_library_activity FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_library_settings, public.community_library_sections, public.community_library_items, public.community_library_purchases, public.community_library_activity TO service_role;
REVOKE ALL ON FUNCTION public.community_library_touch(uuid, uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_library_touch(uuid, uuid, text) TO service_role;
notify pgrst, 'reload schema';
